#!/usr/bin/env node
// `claude-<alias>` (generated by the agent from the aliases the server sends this machine): reads the local copy of
// the resolved aliases, writes that alias's settings slice to a private temp file, and starts Claude Code with
// `--settings <file>`. The key is never on a command line. `proxy` decides the environment for this launch:
//   inherit  leave the shell / ~/.ametyping/launch.* proxy as it is
//   direct   clear the proxy for this process (DeepSeek and the like)
//   http(s)://...  use this proxy
// AME_CLAUDE_API is passed on so the hook relay can tell which alias the session runs with (resume uses it again).
'use strict';
const fs = require('fs');
const os = require('os');
const path = require('path');
const { spawn } = require('child_process');

const HOME = os.homedir();
const MIRROR = path.join(HOME, '.ametyping', 'claude-apis.local.json');
const TMP = path.join(HOME, '.ametyping', 'tmp');
const PROXY_KEYS = ['HTTP_PROXY', 'HTTPS_PROXY', 'ALL_PROXY', 'http_proxy', 'https_proxy', 'all_proxy'];
const NO_PROXY_KEYS = ['NO_PROXY', 'no_proxy'];
const BASE_KEYS = ['env', 'model', 'effortLevel', 'modelSettings', 'alwaysThinkingEnabled', 'language'];
const id = process.argv[2];
const args = process.argv.slice(3);

function fail(msg) { try { process.stderr.write(`claude-${id || '?'}: ${msg}\n`); } catch {} process.exit(2); }
if (!id || !/^[A-Za-z0-9._-]{1,40}$/.test(id)) fail('用法：claude-<别名> [claude 的参数...]');
let cfg;
try { cfg = JSON.parse(fs.readFileSync(MIRROR, 'utf8')); } catch { fail('读不到本机别名配置（agent 还没同步过）'); }
const a = cfg && cfg.aliases && cfg.aliases[id];
if (!a) fail(`这台机器没有别名 ${id}`);
// the machine's own settings are the base (proxy, model); the alias overlays its API values
function baseSettings() {
  try {
    const f = process.env.AME_CLAUDE_SETTINGS || path.join(HOME, '.claude', 'settings.json');
    const j = JSON.parse(fs.readFileSync(f, 'utf8'));
    const out = {};
    for (const k of BASE_KEYS) if (j[k] != null) out[k] = j[k];
    return out;
  } catch { return {}; }
}
function mergeSettings(base, over) {
  const out = JSON.parse(JSON.stringify(base && typeof base === 'object' ? base : {}));
  for (const [k, v] of Object.entries(over && typeof over === 'object' ? over : {})) {
    if (k === 'env') out.env = { ...(out.env && typeof out.env === 'object' ? out.env : {}), ...(v && typeof v === 'object' ? v : {}) };
    else if (k === 'modelSettings') out.modelSettings = { ...(out.modelSettings && typeof out.modelSettings === 'object' ? out.modelSettings : {}), ...(v && typeof v === 'object' ? v : {}) };
    else out[k] = v;
  }
  return out;
}
const settings = mergeSettings(baseSettings(), a.settings);
if (!settings.env || typeof settings.env !== 'object') settings.env = {};
for (const k of Object.keys(settings.env)) if (/^AME_/.test(k) || /^CLAUDE_CONFIG_DIR$/i.test(k)) delete settings.env[k];   // marker / default memory
const proxy = a.proxy === 'direct' || /^https?:\/\//.test(a.proxy || '') ? a.proxy : 'inherit';
if (proxy === 'direct') {
  for (const k of PROXY_KEYS) settings.env[k] = '';
  settings.env.NO_PROXY = '*'; settings.env.no_proxy = '*';
} else if (proxy !== 'inherit') {
  for (const k of PROXY_KEYS) settings.env[k] = proxy;
  settings.env.NO_PROXY = 'localhost,127.0.0.1'; settings.env.no_proxy = 'localhost,127.0.0.1';
}
let tmp = '';
try {
  fs.mkdirSync(TMP, { recursive: true, mode: 0o700 });
  // old sessions' files, kept until their Claude exited; anything older is garbage
  for (const f of fs.readdirSync(TMP)) {
    if (!/^claude-api-.*\.json$/.test(f)) continue;
    const p = path.join(TMP, f);
    try { if (Date.now() - fs.statSync(p).mtimeMs > 86400e3) fs.unlinkSync(p); } catch {}
  }
  tmp = path.join(TMP, `claude-api-${process.pid}-${Date.now().toString(36)}.json`);
  fs.writeFileSync(tmp, JSON.stringify(settings, null, 1), { mode: 0o600 });
} catch (e) { fail('写临时设置失败：' + e.message); }

function findClaude() {
  const names = process.platform === 'win32' ? ['claude.exe', 'claude.cmd'] : ['claude'];
  for (const d of (process.env.PATH || '').split(path.delimiter)) {
    for (const n of names) { const f = d && path.join(d, n); if (f && fs.existsSync(f)) return f; }
  }
  for (const n of names) { const f = path.join(HOME, '.local', 'bin', n); if (fs.existsSync(f)) return f; }
  return '';
}
// AME_CLAUDE_BIN: a specific claude (a test, or a version of your own)
const bin = process.env.AME_CLAUDE_BIN || findClaude();
if (!bin) { try { fs.unlinkSync(tmp); } catch {} fail('找不到 claude'); }
const env = { ...process.env, AME_CLAUDE_API: id };
delete env.CLAUDE_CONFIG_DIR;                                 // every alias uses the default ~/.claude memory
if (proxy === 'direct') {
  for (const k of PROXY_KEYS) delete env[k];
  for (const k of NO_PROXY_KEYS) env[k] = '*';
} else if (proxy !== 'inherit') {
  for (const k of PROXY_KEYS) env[k] = proxy;
  for (const k of NO_PROXY_KEYS) env[k] = 'localhost,127.0.0.1';
}
// the alias is authoritative: a shell that exported another API must not win over --settings
for (const [k, v] of Object.entries(settings.env || {})) {
  if (PROXY_KEYS.includes(k) || NO_PROXY_KEYS.includes(k)) continue;
  env[k] = String(v);
}
env.AME_CLAUDE_API = id;                                      // never let a settings entry change the session marker
// one argument for `cmd.exe /s /c`: always quoted, so & | < > ( ) ^ are literal; characters cmd would expand
// (%, !) or that cannot be represented inside the quotes are refused. The native claude.exe does not go through this.
function cmdArg(s) {
  s = String(s);
  if (/[\r\n"%!]/.test(s)) throw new Error('claude.cmd 不能安全传递包含引号、% 或换行符的参数；请用 claude.exe 或交互模式');
  return `"${s}"`;
}
const argv = ['--settings', tmp, ...args];
let child;
if (process.platform === 'win32' && /\.(cmd|bat)$/i.test(bin)) {
  let line;
  try { line = [bin, ...argv].map(cmdArg).join(' '); }
  catch (e) { try { fs.unlinkSync(tmp); } catch {} fail(e.message); }
  // the extra pair of quotes is what /s expects; windowsVerbatimArguments keeps Node from re-quoting the line
  child = spawn(process.env.ComSpec || 'cmd.exe', ['/d', '/s', '/c', `"${line}"`],
    { cwd: process.cwd(), env, stdio: 'inherit', windowsHide: false, windowsVerbatimArguments: true });
} else {
  child = spawn(bin, argv, { cwd: process.cwd(), env, stdio: 'inherit', windowsHide: false });
}
const clean = () => { try { fs.unlinkSync(tmp); } catch {} };
child.on('error', (e) => { clean(); process.stderr.write(`启动 claude 失败：${e.message}\n`); process.exit(2); });
child.on('exit', (code, sig) => { clean(); process.exit(code == null ? (sig ? 1 : 0) : code); });
